"use client"

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

interface Department {
  id: number;
  name: string;
  description: string;
}

export default function Departaments() {
  const [departments, setDepartments] = useState<Department[]>([
    { id: 1, name: "IT", description: "Информационные технологии" },
    { id: 2, name: "HR", description: "Человеческие ресурсы" },
  ]);

  const [newDept, setNewDept] = useState({ name: "", description: "" });
  const [editing, setEditing] = useState<Department | null>(null);

  const addDepartment = () => {
    if (newDept.name.trim()) {
      const id = Math.max(...departments.map(d => d.id), 0) + 1;
      setDepartments([...departments, { id, ...newDept }]);
      setNewDept({ name: "", description: "" });
    }
  };

  const deleteDepartment = (id: number) => {
    setDepartments(departments.filter(d => d.id !== id));
  };

  const startEdit = (dept: Department) => {
    setEditing(dept);
  };

  const saveEdit = () => {
    if (editing) {
      setDepartments(departments.map(d => d.id === editing.id ? editing : d));
      setEditing(null);
    }
  };

  return (
    <div className="p-8 bg-background min-h-screen text-foreground">
      <h1 className="text-3xl font-bold mb-8">Департаменты</h1>

      {/* Форма добавления */}
      <Card className="mb-8">
        <CardHeader>
          <CardTitle>Добавить департамент</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <Input
            placeholder="Название департамента"
            value={newDept.name}
            onChange={(e: React.ChangeEvent<HTMLInputElement>) => setNewDept({ ...newDept, name: e.target.value })}
          />
          <Input
            placeholder="Описание"
            value={newDept.description}
            onChange={(e: React.ChangeEvent<HTMLInputElement>) => setNewDept({ ...newDept, description: e.target.value })}
          />
          <Button onClick={addDepartment}>Добавить</Button>
        </CardContent>
      </Card>

      {/* Список департаментов */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {departments.map((dept) => (
          <Card key={dept.id}>
            <CardHeader>
              <CardTitle className="flex justify-between items-center">
                {editing?.id === dept.id ? (
                  <Input
                    value={editing.name}
                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => setEditing({ ...editing, name: e.target.value })}
                  />
                ) : (
                  dept.name
                )}
              </CardTitle>
            </CardHeader>
            <CardContent>
              {editing?.id === dept.id ? (
                <div className="space-y-2">
                  <Input
                    value={editing.description}
                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => setEditing({ ...editing, description: e.target.value })}
                  />
                  <div className="flex gap-2">
                    <Button onClick={saveEdit}>Сохранить</Button>
                    <Button variant="outline" onClick={() => setEditing(null)}>Отмена</Button>
                  </div>
                </div>
              ) : (
                <div>
                  <p className="text-muted-foreground mb-4">{dept.description}</p>
                  <div className="flex gap-2">
                    <Button variant="outline" onClick={() => startEdit(dept)}>Редактировать</Button>
                    <Button variant="destructive" onClick={() => deleteDepartment(dept.id)}>Удалить</Button>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}